import gsap from 'gsap';
import { GRService } from '../../slots/GRService';
import { GRUtils } from '../../slots/utils/GRUtils';
import { GCModel } from './model/GCModel';
import { GCSettings } from './model/GCSettings';
import { CascadeState, GCServiceEvent, ICascadeSettings } from './types';

export class GCService extends GRService {

    public eventFire: GCServiceEvent;

    protected _settings: GCSettings;
    protected _model: GCModel;

    constructor() {
        super();
        this._settings = new GCSettings();
        this._model = new GCModel(this);
        this.addPresets();
        this.addEvents();
    }

    public runCascadeSequence(): void {
        this._model.cascadeComplete = false;
        this._model.cascadeState = GRUtils.buildNumberArray(this._registeredReels.length, CascadeState.PRE_CASCADING);
        // stagger sets states to removal phase.
        for (let $reelIndex: number = 0; $reelIndex < this._registeredReels.length; $reelIndex++) {
            gsap.delayedCall($reelIndex * this._settings.cascadeSettings.cascadeRemoveDelay, () => {
                this.model.invalidateSingleCascadeState($reelIndex, CascadeState.REMOVAL);
            });
        }
    }

    public setCascadeSequence(outcome: number[][], removalLocations: number[][]): void {

        // outcome will be a 2d array with all the symbols for each reel.
        this.model.cascadeOutcome = outcome;
        /*
            e.g [[1,2,3],[4,3,2][5,7,2],[2,4,5][1,4,2]] - this would represent the outcome of a 5 x 3 slot.
        */

        // removalLocations is a 2d array containing symbols that need to be removed. 
        this.model.cascadeLocations = removalLocations;
        /* 
            e.g [[0,1][0],[0],[],[] - this would remove the top 2 symbols of the first reel and top symbol of reel 2 and 3.
        */

    }

    private addPresets(): void {
        // set default cascade settings
        this.coreSettings.snapshotInjection = true;
        this.coreSettings.recursiveTransforming = true;
    }

    private addEvents(): void {
        // add cascade events to eventfire
        Object.assign(this.eventFire.serviceEvent, { ON_CASCADE_COMPLETE: () => { return; } });
        Object.assign(this.eventFire.serviceEvent, { ON_CASCADE_STATE_CHANGED: () => { return; } });
    }

    public get model(): GCModel {
        return this._model;
    }

    public get cascadeSettings(): ICascadeSettings {
        return this._settings.cascadeSettings;
    }

    public set cascadeSettings(settings: ICascadeSettings | Partial<ICascadeSettings>) {
        this._settings.updateCascadeSettings(settings);
    }
}
